#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/syscall.h>
#include <sys/types.h>

// Use the raw syscall number for tgkill
#ifndef SYS_tgkill
#define SYS_tgkill 234 // Common architecture specific value (check your system)
#endif

volatile sig_atomic_t signal_received = 0;

// Signal handler function
void handler(int sig) {
    printf("\n[Handler] Thread %ld received signal %d.\n", (long)syscall(SYS_gettid), sig);
    signal_received = 1;
}

long get_tid() {
    return syscall(SYS_gettid);
}

int main() {
    pid_t tgid = getpid();
    pid_t tid = get_tid();
    int sig = SIGUSR1;
    int ret;

    // 1. Set up the signal handler for SIGUSR1
    struct sigaction sa;
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(sig, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    printf("Main thread (TGID: %d, TID: %d) preparing to signal itself (SIGUSR1).\n", tgid, tid);

    // 2. Invoke tgkill via the raw syscall interface
    // tgkill(pid_t tgid, pid_t tid, int sig)
    ret = syscall(SYS_tgkill, tgid, tid, sig);

    if (ret == -1) {
        perror("tgkill syscall failed");
        // Note: For real applications, one must ensure SYS_tgkill is defined correctly.
        return EXIT_FAILURE;
    }

    printf("tgkill successfully invoked. Waiting for signal...");

    // 3. Wait until the signal handler sets the flag
    while (!signal_received) {
        usleep(100000); // Sleep for 100ms
    }

    printf("\nExiting successfully.\n");
    return EXIT_SUCCESS;
}
